import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 4 An exciting trip","description":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 4 An exciting trip","description":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 3 Please send me a card","link":"/life/english/new-concept/book-2/unit-01/lesson-003"},"next":{"text":"第二册：实践与进步 · Lesson 5 No wrong numbers","link":"/life/english/new-concept/book-2/unit-01/lesson-005"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 3 Please send me a card","link":"/life/english/new-concept/book-2/unit-01/lesson-003"},"next":{"text":"第二册：实践与进步 · Lesson 5 No wrong numbers","link":"/life/english/new-concept/book-2/unit-01/lesson-005"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-004.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-004.md"}'),s={name:"life/english/new-concept/book-2/unit-01/lesson-004.md"};function o(r,e,l,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-4-an-exciting-trip" tabindex="-1">第二册：实践与进步 · Lesson 4 An exciting trip <a class="header-anchor" href="#第二册-实践与进步-·-lesson-4-an-exciting-trip" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 4 An exciting trip&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>朋友第一次独自出国，正在分享已经去过的地方；练习表达经验并分清具体过去时间。本课的语言观察是：描述“截至现在去过几处地方”用 has visited；补充上周的某次参观则换成 visited。两种时态能在同一段落中各负其责。完成学习后，请介绍一次仍在进行的旅行，用完成时概括成果，再用过去式补充一天的细节。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>journey</td><td>/ˈdʒɜːni/</td><td>n.</td><td>旅行</td><td>a long journey</td></tr><tr><td>abroad</td><td>/əˈbrɔːd/</td><td>adv.</td><td>在国外</td><td>study abroad</td></tr><tr><td>visit</td><td>/ˈvɪzɪt/</td><td>v.</td><td>参观；拜访</td><td>visit a museum</td></tr><tr><td>return</td><td>/rɪˈtɜːn/</td><td>v.</td><td>返回</td><td>return home</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>travel abroad — 到国外旅行，abroad 前不加 to</li><li>so far — 到目前为止，常与完成时相配</li></ul><h2 id="语法讲解-现在完成时与过去时间" tabindex="-1">语法讲解：现在完成时与过去时间 <a class="header-anchor" href="#语法讲解-现在完成时与过去时间" aria-label="Permalink to &quot;语法讲解：现在完成时与过去时间&quot;">​</a></h2><p>现在完成时由 have/has 加过去分词构成，连接先前发生的事与现在的结果或经验。明确已经结束的时间，如 yesterday、last Friday，通常要求一般过去时；since 引出起点，for 引出持续长度。动作是否还在持续要结合动词含义判断，不能把所有完成时都译成“已经结束”。gone 通常表示去了尚未回，been 表示到过或已经回来。本课应用：描述“截至现在去过几处地方”用 has visited；补充上周的某次参观则换成 visited。两种时态能在同一段落中各负其责。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Iris has visited three coastal towns this month.</p></blockquote><p>这个月艾瑞丝已经游览了三座海滨小镇。</p><p>has visited 表示本月到现在的经历；three coastal towns 是已完成的数量，this month 在此被理解为尚未结束的时间段。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>has visited yesterday 通常不合适；yesterday 明确结束的时间应配 visited。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>听自己的录音，区分 has visited 中的 /z/ 与 visited 的词尾 /ɪd/，不要漏掉 has。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Iris has visited three coastal towns this month. She visited the smallest one on Monday. She plans to return home next week.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>介绍一次仍在进行的旅行，用完成时概括成果，再用过去式补充一天的细节。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：has visited 表示本月到现在的经历；three coastal towns 是已完成的数量，this month 在此被理解为尚未结束的时间段。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：has visited yesterday 通常不合适；yesterday 明确结束的时间应配 visited。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 have 的正确形式：Iris ___ visited three towns this month.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> has</p><p><strong>解析：</strong> Iris 为第三人称单数，完成时助动词用 has。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>艾瑞丝计划什么时候回家？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Next week.</p><p><strong>解析：</strong> plans to 表示当前计划，不能说她已经回家。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>选择正确表达：She has gone / has been to Rome and is back now.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She has been to Rome and is back now.</p><p><strong>解析：</strong> is back now 说明已经回来，应选 been。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：现在完成时与过去时间。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-003">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-005">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(s,[["render",o]]);export{u as __pageData,b as default};
